from rich.errors import MarkupError
try:
    render('a [/] b')
    emit('no-raise')
except MarkupError as e:
    emit('MarkupError: ' + str(e)[:60])

try:
    from rich import Console
    emit('imported')
except ImportError as e:
    emit(type(e).__name__ + ': ' + str(e).split(' (')[0])

import rich
try:
    emit(rich.__version__)
except AttributeError as e:
    emit('AttributeError: ' + str(e)[:60])

from rich.traceback import Traceback
source = 'def boom():\n    1 / 0\n'
ns = {}
exec(compile(source, '<probe>', 'exec'), ns)
try:
    ns['boom']()
except ZeroDivisionError:
    emit(render(Traceback(show_locals=False, width=60), width=60))

